def verify(draft, preds):
    # preds[i] = target model's token at position i (one pass, k+1 predictions)
    out = []
    for i, tok in enumerate(draft):
        if tok != preds[i]:
            out.append(tok)
            return out
        out.append(tok)
    return out + [preds[len(draft)]]

